\usepackage{tikz}

\newcommand{\fenToBoard}[1]{%
    \begin{tikzpicture}[scale=0.8]
        % Draw the chessboard grid
        \foreach \x in {0,...,7} {
            \foreach \y in {0,...,7} {
                \ifodd\y
                    \ifodd\x
                        \fill[black];
                    \else
