To convert markdown-formatted text to HTML in C++, you can use a library like `commonmark` or `markdown`. Below is an example using `commonmark`, which is a C++ implementation of the CommonMark Markdown specification:

First, ensure you have `commonmark` installed. You can install it via vcpkg or another package manager, or clone the repository and build it manually.

Here's a simple function to perform the conversion:

```cpp
#include <iostream>
#include <string>
#include <commonmark.h>

std::string markdownToHtml(const std::string& markdown) {
    struct commonmark_input_buffer_s inputBuffer;
    struct commonmark_document_s* document;

    // Initialize the input buffer with the markdown text
    inputBuffer = commonmark_input_buffer_from_string(markdown.c_str(), markdown.size());

    // Create a document from the input buffer
    document = commonmark_document_new();
    commonmark_parse_document(document, &inputBuffer);

    // Convert the document to HTML
    char* html = commonmark_html_document(document);
    std::string result(html);
    free(html);  // Free the allocated memory

    // Clean up
    commonmark_document_free(document);
    commonmark_input_buffer_free(&inputBuffer);

    return result;
}

int main() {
    std::string markdown = "# Hello, World!\n\nThis is a *markdown* example.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
